/**
 * The seven versioned instructions, ported character-for-character from
 * `backend/ai/prompts/registry.py`.
 *
 * Why this file is a literal transcription instead of a template engine: an `llm_run` row stores the
 * prompt version, and that version is only meaningful if the exact instruction is reproducible. The
 * golden vectors (`tests/golden/ai_prompts.json`) are generated by calling the real Python builders,
 * so every space, newline and placeholder fallback below is pinned by a diff, not by review.
 *
 * Everything here is pure: no clock, no storage, no DSH imports. Values that come from the database
 * (Decimal scores, labels) are interpolated with `pyStr`, because a Python f-string calls `str()`.
 */
import { pyJoin, pyOr, pySlice, pyStr, pyStrip, pyTruthy } from './pyvalue.ts'

export const EXTRACT_PROMPT_VERSION = 'p0-extract-v1'
export const EXPLAIN_PROMPT_VERSION = 'p0-explain-v1'
export const SUGGEST_TAGS_PROMPT_VERSION = 'p1-suggest-tags-v1'
export const TRANSCRIBE_PROMPT_VERSION = 'p1-transcribe-v1'
export const ESTIMATE_GRADE_PROMPT_VERSION = 'p1-estimate-grade-v1'
export const DIAGNOSE_PROMPT_VERSION = 'p1-diagnose-v1'
export const PROPOSE_VARIANT_PROMPT_VERSION = 'p2-propose-variant-v1'

export type PromptVersion =
  | typeof EXTRACT_PROMPT_VERSION
  | typeof EXPLAIN_PROMPT_VERSION
  | typeof SUGGEST_TAGS_PROMPT_VERSION
  | typeof TRANSCRIBE_PROMPT_VERSION
  | typeof ESTIMATE_GRADE_PROMPT_VERSION
  | typeof DIAGNOSE_PROMPT_VERSION
  | typeof PROPOSE_VARIANT_PROMPT_VERSION

/** Prompt version per capability, in `CAPABILITIES` order (the audit record stores both). */
export const PROMPT_VERSIONS = {
  extract_question: EXTRACT_PROMPT_VERSION,
  explain: EXPLAIN_PROMPT_VERSION,
  suggest_tags: SUGGEST_TAGS_PROMPT_VERSION,
  transcribe_handwriting: TRANSCRIBE_PROMPT_VERSION,
  estimate_grade: ESTIMATE_GRADE_PROMPT_VERSION,
  diagnose: DIAGNOSE_PROMPT_VERSION,
  propose_variant: PROPOSE_VARIANT_PROMPT_VERSION,
} as const

/** The only error causes a diagnosis may propose (registry.DIAGNOSIS_ERROR_TYPES). */
export const DIAGNOSIS_ERROR_TYPES = [
  'concept_gap',
  'misread_question',
  'calculation_slip',
  'unit_or_sign_error',
  'incomplete_reasoning',
  'method_misapplied',
  'guessing',
  'unknown',
] as const
export type DiagnosisErrorType = (typeof DIAGNOSIS_ERROR_TYPES)[number]

export const EXTRACT_SYSTEM = `你是考试题库录入助手。你的唯一任务是把图片中的题目转换成结构化候选数据。
严格规则：
1. 只输出 JSON，不要输出解释文字或 Markdown 代码块。
2. 不得编造题目中不存在的内容；识别不清的字段留空，并在 doubts 中说明。
3. 不得推断官方答案；如果图片中没有答案，answer_status_known 必须为 false。
4. 选项 ID 使用 opt_a、opt_b…；空位 ID 使用 b1、b2…（按出现顺序）。
5. 保留负号、单位、上下标等符号信息，不要“修正”成看起来更合理的内容。
输出 JSON 结构：
{
  "question_type": "single_choice|multiple_choice|true_false|fill_blank|constructed_response|material",
  "display_label": "题号或标签（可为空字符串）",
  "content": {"blocks": [{"kind": "text", "text": "..."}], "options": [...], "blanks": [...]},
  "answer_payload": {},
  "answer_status_known": false,
  "source_hint": {"page_index": 1, "note": ""},
  "doubts": ["疑点说明"]
}`

export const EXPLAIN_SYSTEM = `你是考试学习辅导助手。你面对的是固定版本的题目与已核对答案。
严格规则：
1. 只输出 JSON，不要输出解释文字或 Markdown 代码块。
2. 不得修改、重新判定或猜测正式分数；不得声称学生“已掌握”。
3. 不得引用本次输入之外的材料；citations 只能使用给出的引用 ID。
4. 若输入信息不足，把缺失项写进 missing_information，不要编造。
5. 不给出通过率、提分承诺或排名。
输出 JSON 结构：
{
  "key_conditions": ["关键条件"],
  "stuck_points": ["可能卡点"],
  "explanation_blocks": [{"kind": "text", "text": "讲解"}],
  "method_summary": "方法与适用边界",
  "suggested_next": ["下一步验证动作"],
  "missing_information": ["缺失信息"],
  "citations": ["允许的引用 ID"]
}`

export const SUGGEST_TAGS_SYSTEM = `你是考试题库的标签助手。你的唯一任务是为一道题目从给定大纲中挑选可能相关的考点。
严格规则：
1. 只输出 JSON，不要输出解释文字或 Markdown 代码块。
2. 只能从“允许的考点名称”列表中选择，必须逐字复制名称，不得改写、缩写或创造新名称。
3. 不确定就不要给；宁可少给，也不要为了凑数而猜。
4. 不得输出分数、掌握程度或通过率。
输出 JSON 结构：
{"tags": [{"name": "考点名称（逐字复制）", "confidence": 0.0, "rationale": "为什么相关（不超过 60 字）"}]}`

export const TRANSCRIBE_SYSTEM = `你是手写作答的转写助手。你的唯一任务是把照片中的手写内容转写成文字。
严格规则：
1. 只输出 JSON，不要输出解释文字或 Markdown 代码块。
2. 只转写照片中真实存在的内容；看不清的字用“□”占位，并把位置写进 doubts。
3. 不要纠正、补全或“猜”学习者的推导；不要替他算出答案。
4. 不要判断对错，不要给分数，不要写掌握程度。
5. 如果整张图都看不清，text 返回空字符串并把 illegible 设为 true。
输出 JSON 结构：
{"text": "转写文本", "confidence": 0.0, "doubts": ["不确定之处"], "illegible": false}`

export const ESTIMATE_SYSTEM = `你是考试评分辅助助手。你要按给定的评分点，为一份作答给出**参考估计**。
严格规则：
1. 只输出 JSON，不要输出解释文字或 Markdown 代码块。
2. 只能使用给定的 criterion_id，不得新增、删除或改写评分点。
3. 每个评分点的分数必须在 0 与它的 max_score 之间；不确定就给低分并在 missing_evidence 说明。
4. 这是“参考估计”，不是正式分数：不得声称已确认，不得写“已掌握/通过/及格”。
5. 没有过程证据时不要断言粗心或态度问题。
输出 JSON 结构：
{"criteria": [{"criterion_id": "...", "estimated_score": 0, "rationale": "...", "missing_evidence": ["..."]}],
 "overall_note": "...", "confidence": 0.0}`

export const DIAGNOSE_SYSTEM = `你是学习诊断助手。你要根据一份作答，提出**可能的**错误原因与需要向学习者追问的问题。
严格规则：
1. 只输出 JSON，不要输出解释文字或 Markdown 代码块。
2. error_type 只能从给定列表中选；证据不足时用 unknown，不要为了凑数而猜。
3. 不得修改分数、不得给出掌握结论、不得声称学习者“粗心”或态度问题。
4. 每个原因必须给出可核对的 evidence（引用作答或题干中的具体内容）。
5. follow_up_questions 是让学习者补充过程证据的问题，必须具体、可回答。
输出 JSON 结构：
{"causes": [{"error_type": "...", "confidence": 0.0, "evidence": ["..."]}],
 "follow_up_questions": [{"question": "...", "why": "...", "evidence_kind": "过程步骤|口算过程|题意理解|单位与符号"}],
 "missing_information": ["..."]}`

export const VARIANT_SYSTEM = `你是考试题库的变式题生成助手。你的唯一任务是基于一道已审核的题目，生成一道**新的**同考点变式题候选。
严格规则：
1. 只输出 JSON，不要输出解释文字或 Markdown 代码块。
2. 变式必须是新题：不得照抄原题干，不得只改数字后与原题雷同；题干条件必须完整、自洽。
3. 答案必须能由你自己给出的题干独立推出；不得直接抄写原题答案，也不得把答案写进题干或选项。
4. 单选题只能有一个正确选项；多选题至少两个正确选项，且必须真实存在于选项中。
5. 题型必须与给定题型一致；不得输出 material（共享材料）。
6. 选项 ID 用 opt_a、opt_b…；空位 ID 用 b1、b2…；answer_payload.kind 必须等于题型。
7. 填空题每个空位都必须给出非空的 accepted_values 字符串数组，且空位 ID 与题干一致。
8. 大题必须给出 rubric_criteria（每个评分点有正的 max_score）与 rubric_total_score（等于各评分点之和）。
9. 不得引用图片：content 中不得出现 image 块（你无法知道真实资产 ID）。
10. 你的输出只是候选：不会自动发布，仍需人工逐项核对并确认答案。
输出 JSON 结构：
{
  "question_type": "single_choice|multiple_choice|true_false|fill_blank|constructed_response",
  "content": {"blocks": [{"kind": "text", "text": "..."}], "options": [...], "blanks": [...]},
  "answer_payload": {"kind": "题型", "...": "按题型给出的可判定答案"},
  "rubric_criteria": [{"criterion_id": "c1", "text": "...", "max_score": "2.00", "required": true}],
  "rubric_total_score": "2.00",
  "practice_max_score": "2.00",
  "difficulty_note": "难度说明",
  "rationale": "与原题的差异（一句话，说明为什么是同一考点的陌生变式）",
  "doubts": ["不确定之处"]
}`

type BlockMap = Readonly<Record<string, unknown>>
type OptionMap = Readonly<Record<string, unknown>>

/**
 * `_blocks_text`: text blocks join their text, math blocks are wrapped in `$`, anything else is
 * dropped and empty parts disappear from the join. A `text` key present with `null` becomes the
 * string `"None"` — that is Python `str(None)`, and it is what the Python builder does too.
 */
export function blocksText(blocks: unknown): string {
  if (!Array.isArray(blocks)) return ''
  const parts: string[] = []
  for (const block of blocks) {
    if (block === null || typeof block !== 'object' || Array.isArray(block)) continue
    const map = block as BlockMap
    if (map.kind === 'text') parts.push(pyStr(Object.hasOwn(map, 'text') ? map.text : ''))
    else if (map.kind === 'math') parts.push(`$${pyStr(Object.hasOwn(map, 'latex') ? map.latex : '')}$`)
  }
  return parts.filter((part) => part.length > 0).join(' ')
}

const field = (map: BlockMap, key: string, fallback: unknown = null): unknown =>
  Object.hasOwn(map, key) ? map[key] : fallback

/** `f"{option.get('label') or option.get('id')}: {_blocks_text(...)}"` */
function optionLine(option: OptionMap): string {
  const label = field(option, 'label')
  const id = field(option, 'id')
  return `- ${pyStr(pyTruthy(label) ? label : id)}: ${blocksText(field(option, 'blocks', null))}`
}

export interface ExtractPromptInput {
  project_name: unknown
  subject_name: unknown
  source_note?: unknown
}

export function buildExtractPrompt({ project_name, subject_name, source_note = '' }: ExtractPromptInput): string {
  return (
    `${EXTRACT_SYSTEM}\n\n` +
    `项目：${pyStr(project_name)}\n科目：${pyStr(subject_name)}\n来源说明：${pyStr(pyOr(source_note, '（未提供）'))}\n` +
    '请识别这张图片中的一道题目，输出 JSON。'
  )
}

export interface ExplainPromptInput {
  question_type: unknown
  stem_text: unknown
  options: readonly OptionMap[]
  answer_summary: unknown
  explanation_blocks: unknown
  allowed_citation_ids: readonly unknown[]
  attempt_summary?: unknown
  user_question?: unknown
  knowledge_nodes?: readonly unknown[] | null
  rubric_criteria?: readonly BlockMap[] | null
  material_text?: unknown
  blanks?: readonly BlockMap[] | null
}

export function buildExplainPrompt(input: ExplainPromptInput): string {
  const {
    question_type, stem_text, options, answer_summary, explanation_blocks,
    allowed_citation_ids, attempt_summary = '', user_question = '', knowledge_nodes = null,
    rubric_criteria = null, material_text = '', blanks = null,
  } = input
  const optionLines = options.map(optionLine).join('\n')
  const blankLines = (blanks ?? [])
    .filter((blank) => blank !== null && typeof blank === 'object')
    .map((blank) => `- ${pyStr(field(blank, 'blank_id'))}: ${pyStr(pyOr(field(blank, 'label'), ''))}`)
    .join('\n')
  const rubricLines = (rubric_criteria ?? [])
    .filter((criterion) => criterion !== null && typeof criterion === 'object')
    .map((criterion) =>
      `- ${pyStr(field(criterion, 'criterion_id'))}（满分 ${pyStr(field(criterion, 'max_score'))}）: ${pyStr(pyOr(field(criterion, 'text'), ''))}`,
    )
    .join('\n')
  const nodeLine = pyJoin('、', knowledge_nodes ?? []) || '（未映射考点）'
  return (
    `${EXPLAIN_SYSTEM}\n\n` +
    `题型：${pyStr(question_type)}\n题干：${pyStr(stem_text)}\n` +
    `选项：\n${optionLines || '（无选项）'}\n` +
    `空位：\n${blankLines || '（无空位）'}\n` +
    `共享材料：${pyStr(pyOr(material_text, '（无共享材料）'))}\n` +
    `关联考点：${nodeLine}\n` +
    `评分标准（人工已审核）：\n${rubricLines || '（本题无逐点评分标准）'}\n` +
    `已核对答案摘要：${pyStr(pyOr(answer_summary, '（本题答案尚未核对，只能做条件澄清，不得给出结论性答案）'))}\n` +
    `已审核人工解析：${blocksText(explanation_blocks) || '（无）'}\n` +
    `学生本次作答（原文，逐字保留；请针对其中具体内容讲解）：\n${pyStr(pyOr(attempt_summary, '（尚未提交作答）'))}\n` +
    `学生问题：${pyStr(pyOr(user_question, '请针对上面学生自己的作答与步骤，给出关键条件、可能卡点、方法与下一步验证。'))}\n` +
    `允许引用的引用 ID（只能使用这些）：${pyJoin(', ', allowed_citation_ids) || '（无）'}\n` +
    '请输出 JSON。'
  )
}

export interface TagSuggestionPromptInput {
  subject_name: unknown
  stem_text: unknown
  option_texts: readonly unknown[]
  allowed_node_names: readonly unknown[]
  material_text?: unknown
}

export function buildTagSuggestionPrompt(input: TagSuggestionPromptInput): string {
  const { subject_name, stem_text, option_texts, allowed_node_names, material_text = '' } = input
  const options = option_texts.filter((text) => pyTruthy(text)).map((text) => `- ${pyStr(text)}`).join('\n') || '（无选项）'
  const allowed =
    pyJoin('\n', Array.from(allowed_node_names).slice(0, 200).map((name) => `- ${pyStr(name)}`)) || '（大纲为空：必须返回空 tags）'
  const material = pyTruthy(material_text) ? `\n共享材料：${pySlice(pyStr(material_text), 1500)}` : ''
  return (
    `${SUGGEST_TAGS_SYSTEM}\n\n` +
    `科目：${pyStr(subject_name)}\n` +
    `题干：${pySlice(pyStr(stem_text), 3000)}\n选项：\n${options}${material}\n\n` +
    `允许的考点名称（只能逐字复制以下名称）：\n${allowed}\n\n` +
    '请输出 JSON。'
  )
}

export interface TranscribePromptInput {
  subject_name: unknown
  question_stem?: unknown
  note?: unknown
}

export function buildTranscribePrompt({ subject_name, question_stem = '', note = '' }: TranscribePromptInput): string {
  return (
    `${TRANSCRIBE_SYSTEM}\n\n` +
    `科目：${pyStr(subject_name)}\n` +
    `题目（仅供理解上下文，不要在转写里复制）：${pySlice(pyStr(question_stem), 800) || '（未提供）'}\n` +
    `补充说明：${pyStr(pyOr(note, '（无）'))}\n` +
    '请转写这张照片中的手写作答，输出 JSON。'
  )
}

export interface EstimatePromptInput {
  question_type: unknown
  stem_text: unknown
  rubric_criteria: readonly BlockMap[]
  learner_answer_text: unknown
  transcription_note?: unknown
  max_total?: unknown
}

export function buildEstimatePrompt(input: EstimatePromptInput): string {
  const { question_type, stem_text, rubric_criteria, learner_answer_text, transcription_note = '', max_total = '' } = input
  const criteriaLines = rubric_criteria
    .map((criterion) =>
      `- criterion_id=${pyStr(field(criterion, 'criterion_id'))} · 满分 ${pyStr(field(criterion, 'max_score'))} · ` +
      `${pySlice(pyStr(pyOr(field(criterion, 'description'), '')), 300)}`,
    )
    .join('\n')
  return (
    `${ESTIMATE_SYSTEM}\n\n` +
    `题型：${pyStr(question_type)}\n题干：${pySlice(pyStr(stem_text), 2000)}\n` +
    `评分点（只能使用这些 criterion_id）：\n${criteriaLines || '（无评分点）'}\n` +
    `整题满分：${pyStr(pyOr(max_total, '（未提供）'))}\n` +
    `学习者作答（文字与已确认的转写）：${pySlice(pyStr(learner_answer_text), 4000) || '（没有可读文本）'}\n` +
    `转写说明：${pyStr(pyOr(transcription_note, '（无）'))}\n` +
    '请按评分点给出参考估计，输出 JSON。'
  )
}

export interface DiagnosePromptInput {
  question_type: unknown
  stem_text: unknown
  answer_summary: unknown
  learner_answer_text: unknown
  graded_parts: readonly BlockMap[]
  transcription_note?: unknown
}

export function buildDiagnosePrompt(input: DiagnosePromptInput): string {
  const { question_type, stem_text, answer_summary, learner_answer_text, graded_parts, transcription_note = '' } = input
  const parts = graded_parts
    .slice(0, 30)
    .map((part) => {
      // `a or b or c or ''`: the first truthy identifier, in that order.
      const identifier = pyOr(pyOr(pyOr(field(part, 'criterion_id'), field(part, 'blank_id')), field(part, 'part_id')), '')
      return `- ${pyStr(identifier)}: 得分 ${pyStr(field(part, 'score'))} / ${pyStr(field(part, 'max_score'))}`
    })
    .join('\n')
  return (
    `${DIAGNOSE_SYSTEM}\n\n` +
    `题型：${pyStr(question_type)}\n题干：${pySlice(pyStr(stem_text), 2000)}\n` +
    `已核对答案（仅供你判断，不要直接抄给学习者）：${pySlice(pyStr(answer_summary), 1000)}\n` +
    `学习者作答：${pySlice(pyStr(learner_answer_text), 3000) || '（没有可读文本）'}\n` +
    `评分点得分：\n${parts || '（无逐点得分）'}\n` +
    `转写说明：${pyStr(pyOr(transcription_note, '（无）'))}\n` +
    `允许的 error_type：${pyJoin(', ', DIAGNOSIS_ERROR_TYPES)}\n` +
    '请给出可能原因与追问问题，输出 JSON。'
  )
}

export interface VariantPromptInput {
  question_type: unknown
  stem_text: unknown
  options: readonly OptionMap[]
  answer_summary: unknown
  node_name: unknown
  difficulty_note: unknown
  avoid_stems?: Iterable<unknown>
  rubric_criteria?: readonly BlockMap[] | null
  material_text?: unknown
}

export function buildVariantPrompt(input: VariantPromptInput): string {
  const {
    question_type, stem_text, options, answer_summary, node_name, difficulty_note,
    avoid_stems = [], rubric_criteria = null, material_text = '',
  } = input
  const optionLines = options
    .filter((option) => option !== null && typeof option === 'object')
    .map(optionLine)
    .join('\n')
  const rubricLines = (rubric_criteria ?? [])
    .filter((criterion) => criterion !== null && typeof criterion === 'object')
    .map((criterion) =>
      `- ${pyStr(field(criterion, 'criterion_id'))}（满分 ${pyStr(field(criterion, 'max_score'))}）: ${pySlice(pyStr(pyOr(field(criterion, 'text'), '')), 200)}`,
    )
    .join('\n')
  const avoidLines = Array.from(avoid_stems)
    .filter((stem) => pyStrip(pyStr(pyOr(stem, ''))) !== '')
    .map((stem) => `- ${pySlice(pyStr(stem), 400)}`)
    .join('\n')
  return (
    `${VARIANT_SYSTEM}\n\n` +
    `题型：${pyStr(question_type)}\n` +
    `目标考点：${pyStr(pyOr(node_name, '（未指定）'))}\n` +
    `原题题干（不得照抄，也不得只改数字后雷同）：${pySlice(pyStr(pyOr(stem_text, '')), 3000) || '（未提供）'}\n` +
    `原题选项：\n${optionLines || '（无选项）'}\n` +
    `原题评分标准（仅供理解考查方式，不要照抄评分点文字）：\n${rubricLines || '（无）'}\n` +
    `共享材料：${pySlice(pyStr(pyOr(material_text, '')), 1500) || '（无）'}\n` +
    `原题已核对答案（仅供你理解考点；你的变式必须自己可解，不得直接照抄这个答案）：` +
    `${pySlice(pyStr(pyOr(answer_summary, '')), 1000) || '（原题答案尚未核对：只能依据题干条件生成）'}\n` +
    `必须避免的题干（不得与以下任一题干相同或仅改数字）：\n${avoidLines || '（无）'}\n` +
    `难度要求：${pyStr(pyOr(difficulty_note, '（未指定：保持与原题相当）'))}\n` +
    '请输出一道变式题的 JSON。'
  )
}
